package com.bank.qa.chaos;

import java.util.logging.*;

public class ChaosDemo {
    private static final Logger log = Logger.getLogger(ChaosDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ChLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    // Runs one chaos experiment with hypothesis, small blast radius, and abort.
    private static void experiment(String label, ServiceCluster cluster, double steadyStateMinPct) {
        log.info("=== Experiment: " + label + " ===");
        log.info("Steady state: success rate >= " + steadyStateMinPct + "%");
        log.info("Hypothesis: killing 1 instance keeps success rate >= steady state");
        double before = cluster.successRatePct();
        log.info("before: healthy=" + cluster.healthy() + "/" + cluster.total()
            + " success=" + before + "%");

        cluster.killInstance();   // INJECT FAULT (small blast radius: one instance)

        double after = cluster.successRatePct();
        log.info("after kill: healthy=" + cluster.healthy() + "/" + cluster.total()
            + " success=" + after + "%");

        if (after >= steadyStateMinPct) {
            log.info("RESULT: steady state HELD -> resilience confirmed");
        } else {
            log.severe("RESULT: steady state BREACHED -> ABORT experiment + rollback; "
                + "weakness found (no failover) to fix BEFORE a real outage");
        }
    }

    public static void main(String[] args) {
        // Resilient cluster: failover reroutes, steady state holds.
        experiment("Kill 1 of 3 (with failover)", new ServiceCluster(3, true), 99.0);

        // Fragile cluster: no failover, steady state breaches -> abort + learn.
        experiment("Kill 1 of 3 (NO failover)", new ServiceCluster(3, false), 99.0);
    }
}

